import{_ as n,a0 as r,w as l,s,I as e,x as o,a1 as p,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何在 CentOS 7 上安装开源 ITIL 门户 iTOP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 7 上安装开源 ITIL 门户 iTOP | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 7 上安装开源 ITIL 门户 iTOP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 7 上安装开源 ITIL 门户 iTOP | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7","title":"如何在 CentOS 7 上安装开源 ITIL 门户 iTOP","tag":"201509","desc":""},"relativePath":"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7.md","filePath":"[post].md"}'),m={name:"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7.md"};function h(c,t,T,g,b,w){const i=r("Link");return l(),s("div",null,[t[16]||(t[16]=e("h1",{id:"如何在-centos-7-上安装开源-itil-门户-itop",tabindex:"-1"},[o("如何在 CentOS 7 上安装开源 ITIL 门户 iTOP "),e("a",{class:"header-anchor",href:"#如何在-centos-7-上安装开源-itil-门户-itop","aria-label":"Permalink to “如何在 CentOS 7 上安装开源 ITIL 门户 iTOP”"},"​")],-1)),t[17]||(t[17]=e("p",null,"iTOP是一个简单的基于Web的开源IT服务管理工具。它有所有的ITIL功能，包括服务台、配置管理、事件管理、问题管理、变更管理和服务管理。iTOP依赖于Apache/IIS、MySQL和PHP，因此它可以运行在任何支持这些软件的操作系统中。因为iTOP是一个Web程序，因此你不必在用户的PC端任何客户端程序。一个简单的浏览器就足够每天的IT环境操作了。",-1)),t[18]||(t[18]=e("p",null,"我们要在一台有满足基本需求的LAMP环境的CentOS 7上安装和配置iTOP。",-1)),t[19]||(t[19]=e("h3",{id:"下载-itop",tabindex:"-1"},[o("下载 iTOP "),e("a",{class:"header-anchor",href:"#下载-itop","aria-label":"Permalink to “下载 iTOP”"},"​")],-1)),e("p",null,[t[1]||(t[1]=o("iTOP的下载包现在在SourceForge上，我们可以从这获取它的官方",-1)),p(i,{href:"http://www.combodo.com/spip.php?page=rubrique&id_rubrique=8"},{default:a(()=>[...t[0]||(t[0]=[o("链接",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),t[20]||(t[20]=d(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/1-itop-download.png" alt="itop download"></p><p>我们从这里的连接用wget命令获取压缩文件。</p><pre><code>[root@centos-007 ~]# wget http://downloads.sourceforge.net/project/itop/itop/2.1.0/iTop-2.1.0-2127.zip
</code></pre><h3 id="itop扩展和网络安装" tabindex="-1">iTop扩展和网络安装 <a class="header-anchor" href="#itop扩展和网络安装" aria-label="Permalink to “iTop扩展和网络安装”">​</a></h3><p>使用unzip命令解压到apache根目录下的itop文件夹下。</p><pre><code>[root@centos-7 ~]# ls
iTop-2.1.0-2127.zip
[root@centos-7 ~]# unzip iTop-2.1.0-2127.zip -d /var/www/html/itop/
</code></pre><p>列出安装包中的内容。</p><pre><code>[root@centos-7 ~]# ls -lh /var/www/html/itop/
total 68K
-rw-r--r--. 1 root root 1.4K Dec 17 2014 INSTALL
-rw-r--r--. 1 root root 35K Dec 17 2014 LICENSE
-rw-r--r--. 1 root root 23K Dec 17 2014 README
drwxr-xr-x. 19 root root 4.0K Jul 14 13:10 web
</code></pre><p>这些是我们可以安装的扩展。</p><pre><code>[root@centos-7 2.x]# ls
authent-external itop-backup itop-config-mgmt itop-problem-mgmt itop-service-mgmt-provider itop-welcome-itil
authent-ldap itop-bridge-virtualization-storage itop-datacenter-mgmt itop-profiles-itil itop-sla-computation version.xml
authent-local itop-change-mgmt itop-endusers-devices itop-request-mgmt itop-storage-mgmt wizard-icons
installation.xml itop-change-mgmt-itil itop-incident-mgmt-itil itop-request-mgmt-itil itop-tickets
itop-attachments itop-config itop-knownerror-mgmt itop-service-mgmt itop-virtualization-mgmt
</code></pre><p>在解压的目录下，使用如下的 cp 命令将不同的数据模型从web 下的 datamodels 目录下复制到 extensions 目录，来迁移需要的扩展。</p><pre><code>[root@centos-7 2.x]# pwd
/var/www/html/itop/web/datamodels/2.x
[root@centos-7 2.x]# cp -r itop-request-mgmt itop-service-mgmt itop-service-mgmt itop-config itop-change-mgmt /var/www/html/itop/web/extensions/
</code></pre><h3 id="安装-itop-web界面" tabindex="-1">安装 iTop web界面 <a class="header-anchor" href="#安装-itop-web界面" aria-label="Permalink to “安装 iTop web界面”">​</a></h3><p>大多数服务端设置和配置已经完成了。最后我们安装web界面来完成安装。</p><p>打开浏览器使用ip地址或者完整域名来访问iTop 的 web目录。</p><pre><code>http://servers_ip_address/itop/web/
</code></pre><p>你会被重定向到iTOP的web安装页面。让我们按照要求配置，就像在这篇教程中做的那样。</p><h4 id="验证先决要求" tabindex="-1">验证先决要求 <a class="header-anchor" href="#验证先决要求" aria-label="Permalink to “验证先决要求”">​</a></h4><p>这一步你就会看到验证完成的欢迎界面。如果你看到了一些警告信息，你需要先安装这些软件来解决这些问题。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/2-itop-web-install.png" alt="mcrypt missing"></p><p>这一步有一个叫php mcrypt的可选包丢失了。下载下面的rpm包接着尝试安装php mcrypt包。</p><pre><code>[root@centos-7 ~]#yum localinstall php-mcrypt-5.3.3-1.el6.x86_64.rpm libmcrypt-2.5.8-9.el6.x86_64.rpm.
</code></pre><p>成功安装完php-mcrypt后，我们需要重启apache服务，接着刷新页面，这时验证应该已经OK。</p><h4 id="安装或者升级-itop" tabindex="-1">安装或者升级 iTop <a class="header-anchor" href="#安装或者升级-itop" aria-label="Permalink to “安装或者升级 iTop”">​</a></h4><p>现在我们要在没有安装iTOP的服务器上选择全新安装。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/3.png" alt="Install New iTop"></p><h4 id="itop-许可协议" tabindex="-1">iTop 许可协议 <a class="header-anchor" href="#itop-许可协议" aria-label="Permalink to “iTop 许可协议”">​</a></h4><p>勾选接受 iTOP所有组件的许可协议，并点击“NEXT”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/4.png" alt="License Agreement"></p><h4 id="数据库配置" tabindex="-1">数据库配置 <a class="header-anchor" href="#数据库配置" aria-label="Permalink to “数据库配置”">​</a></h4><p>现在我们输入数据库凭据来配置数据库连接，接着选择如下选择创建新数据库。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/5.png" alt="DB Connection"></p><h4 id="管理员账户" tabindex="-1">管理员账户 <a class="header-anchor" href="#管理员账户" aria-label="Permalink to “管理员账户”">​</a></h4><p>这一步中我们会输入它的登录信息来配置管理员账户。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/6.png" alt="Admin Account"></p><h4 id="杂项参数" tabindex="-1">杂项参数 <a class="header-anchor" href="#杂项参数" aria-label="Permalink to “杂项参数”">​</a></h4><p>让我们选择额外的参数来选择你是否需要安装一个带有演示内容的数据库或者使用全新的数据库，接着下一步。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/7.png" alt="Misc Parameters"></p><h3 id="itop-配置管理" tabindex="-1">iTop 配置管理 <a class="header-anchor" href="#itop-配置管理" aria-label="Permalink to “iTop 配置管理”">​</a></h3><p>下面的选项允许你配置在iTOP要管理的元素类型，像CMDB、数据中心设备、存储设备和虚拟化这些东西在iTOP中是必须的。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/8.png" alt="Conf Management"></p><h4 id="服务管理" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理" aria-label="Permalink to “服务管理”">​</a></h4><p>选择一个最能描述你的IT设备和环境之间的关系的选项。因此我们这里选择为服务提供商的服务管理。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/9.png" alt="Service Management"></p><h4 id="itop-tickets-管理" tabindex="-1">iTop Tickets 管理 <a class="header-anchor" href="#itop-tickets-管理" aria-label="Permalink to “iTop Tickets 管理”">​</a></h4><p>从不同的可用选项我们选择符合ITIL Tickets管理选项来管理不同类型的用户请求和事件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/10.png" alt="Ticket Management"></p><h4 id="改变管理选项" tabindex="-1">改变管理选项 <a class="header-anchor" href="#改变管理选项" aria-label="Permalink to “改变管理选项”">​</a></h4><p>选择不同的ticket类型以便管理可用选项中的IT设备变更。我们选择ITTL变更管理选项。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/11.png" alt="ITIL Change"></p><h4 id="itop-扩展" tabindex="-1">iTop 扩展 <a class="header-anchor" href="#itop-扩展" aria-label="Permalink to “iTop 扩展”">​</a></h4><p>这一节我们选择额外的扩展来安装或者不选直接跳过。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/13.png" alt="iTop Extensions"></p><h3 id="准备开始web安装" tabindex="-1">准备开始web安装 <a class="header-anchor" href="#准备开始web安装" aria-label="Permalink to “准备开始web安装”">​</a></h3><p>现在我们开始准备安装先前先前选择的组件。我们也可以下拉这些安装参数来浏览我们的配置。</p><p>确认安装参数后点击安装按钮。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/16.png" alt="Installation Parameters"></p><p>让我们等待进度条来完成安装步骤。它也许会花费几分钟来完成安装步骤。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/17.png" alt="iTop Installation Process"></p><h3 id="itop安装完成" tabindex="-1">iTop安装完成 <a class="header-anchor" href="#itop安装完成" aria-label="Permalink to “iTop安装完成”">​</a></h3><p>我们的iTOP安装已经完成了，只要如下一个简单的手动操作就可以进入到iTOP。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/18.png" alt="iTop Done"></p><h3 id="欢迎来到itop-it操作门户" tabindex="-1">欢迎来到iTop (IT操作门户) <a class="header-anchor" href="#欢迎来到itop-it操作门户" aria-label="Permalink to “欢迎来到iTop (IT操作门户)”">​</a></h3><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/20.png" alt="itop welcome note"></p><h3 id="itop-面板" tabindex="-1">iTop 面板 <a class="header-anchor" href="#itop-面板" aria-label="Permalink to “iTop 面板”">​</a></h3><p>你这里可以配置任何东西，服务、计算机、通讯录、位置、合同、网络设备等等。你可以创建你自己的。事实是刚安装的CMDB模块是每一个IT人员的必备模块。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/19.png" alt="iTop Dashboard"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>ITOP是一个最棒的开源桌面服务解决方案。我们已经在CentOS 7上成功地安装和配置了。因此，iTOP最强大的一方面是它可以很简单地通过扩展来自定义。如果你在安装中遇到任何问题欢迎评论。</p><hr>`,70)),e("p",null,[t[4]||(t[4]=o("via: ",-1)),p(i,{href:"http://linoxide.com/tools/setup-itop-centos-7/"},{default:a(()=>[...t[3]||(t[3]=[o("http://linoxide.com/tools/setup-itop-centos-7/",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("作者：",-1)),p(i,{href:"http://linoxide.com/author/kashifs/"},{default:a(()=>[...t[5]||(t[5]=[o("Kashif Siddique",-1)])]),_:1}),t[9]||(t[9]=o(" 译者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[o("geekpi",-1)])]),_:1}),t[10]||(t[10]=o(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=o("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原创翻译，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[o("Linux中国",-1)])]),_:1}),t[15]||(t[15]=o(" 荣誉推出",-1))])])}const f=n(m,[["render",h]]);export{P as __pageData,f as default};
